quests[51215] = { id = 51215, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Milking Goats", description = "Unfortunately, Milbrooke's flock hasn't been producing lately. What with all the wolves about, the poor things must be terrified.\n\nWild goats wander the hills, and they are quite fearless compared to the sheep. \n\nIf you can find a few with young ones about, you may be able to persuade them to offer some fresh, delicious goat milk!", progress = "Were you able to collect enough milk?", completion = "It smells wonderful. This is perfect, thank you {name}!", objectives = "Collect 6 Mountain Goat Milk.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[51216] = { id = 51216, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Waycrest Manor: Something to Crow About" }
quests[51217] = { id = 51217, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "WANTED: Yarsel'ghun", description = "By the decree of the Storm's Wake.\n\nFind and kill the foreign spy, Yarsel'ghun. \n\nA foreigner agent hiding on our soil, she is responsible for acts of terrorism against the citizens of Stormsong.\n\nThe individual that ends her existence will earn a fitting reward.", progress = "The wanted poster is nailed to the wall, with tasks etched on it.", completion = "One less Horde in Stormsong.", objectives = "Find and kill Yarsel'ghun.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[51218] = { id = 51218, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Undelivered Package", description = "< The ransacked cart has obviously seen better days. A single package remains, obscured by the spilled grain. It's addressed to Marie Davenport of Millstone Hamlet. >", completion = "Ohhhh, goodness! You found my lost tea. Thank you dear!", objectives = "Deliver the package to Marie Davenport.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[51220] = { id = 51220, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Deep Sea Venture", description = "As mighty as Ai'twen is, this Venture Company is still a threat to him. I need you to watch over Ai'twen and Toki as you continue your great adventure.  \n\nEliminate the Venture Company Seawrenches that lurk the waters you travel to.", progress = "Hurry to it, Ai'twen's saftey is important.", completion = "You've struck a mighty blow against these Venture Company thugs, and kept Ai'twen safe.", objectives = "Eliminate 6 Seawrenches", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[51221] = { id = 51221, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Response Required", completion = "You've bought us valuable time with your heroic actions.", objectives = "Eliminate Lithia Costcutter", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[51222] = { id = 51222, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "What's Yours is Mined", description = "During a visit to Pandaria, I witnessed the citizens of Halfhill defeat attacking hozen by flinging the hozen's excrement back at them.  \n\nThe hozen were unprepared to face the wrath of their own weaponry used against them. A similar strategy can be applied here. We will gather Venture Co. Sea Mines and use them against the invaders.  \n\nYou hook ropes to each mine, and Ai'twen and I will haul them up.", completion = "Excellent work, {name}. Our plan is coming together nicely.", objectives = "Collect 10 Sea Mines", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[51223] = { id = 51223, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Walking on Broken Glass" }
quests[51224] = { id = 51224, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Profit and Reconnaissance", description = "This was supposed to be a covert operation. Unfortunately, our Trade Prince insisted on coming along... with the loudest, most conspicuous vehicle the Horde has ever conceived.\n\nAt least you're here with me, {name}.\n\nLet's get going, then. We know next to nothing about the Drustvar territory. It's time to do some recon.", progress = "Let's get this over with.", completion = "I'm getting a bad feeling about these woods.\n\nWait a minute... what is THAT!?", objectives = "Escort Gallywix and Eitrigg on Gallywix's War Trike.\n\nIf you become separated from Gallywix and Eitrigg, you can find them at Anyport.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[51225] = { id = 51225, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Albatrocity" }
quests[51226] = { id = 51226, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Death from Two Sides", description = "The overgrown lizards from down on the beach decided to swarm the camp suddenly. \n\nWe're used to dealing with one or two each week, but it seems like the whole brood came up the cliff. Wonder if the smell of blood drew them in.\n\nThey're putting our remaining men at risk, wipe them out!", progress = "Have you thinned out those saurolisks yet?", completion = "There's one problem dealt with.", objectives = "Kill 8 Brinefang Saurolisk.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[51228] = { id = 51228, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Instant Meat, Ready to Eat" }
quests[51229] = { id = 51229, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Establish a Beachhead", description = "I won't allow Private Leonard's sacrifice to be in vain. Let's get our men out here and fortify this place up before those... \"sethrak\" decide to come back.\n\nHere, plant this banner somewhere visible so the ship knows its safe. That platform over next to the dock should do the trick.", completion = "The crew's setting up our camp in record time! Good work securing the beachhead.\n\nNow, about Sergeant Ermey...", objectives = "Plant the Alliance banner and establish your base in Vol'dun.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[51230] = { id = 51230, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Emergency Transplants", description = "Riverbud is a precious resource for us. Not only does it have potent magical properties, but it also feeds many of de beasts we train or eat ourselves.\n\nHowever, de Blood Trolls have been dumping a lot of cursed blood in de rivers. It may not be their goal, but if we do not act soon, de pollution may wipe out all de riverbud.\n\nI need you to take dis handful of seeds, and plant dem in de rivermud. In exchange, I will teach you how to harvest it more effectively.", completion = "I cannot thank you enough. Riverbud is absolutely critical to both de Zandalari and to de wildlife. Regardless, I said I would teach you, and I am true to my word.\n\nDe riverbud you have harvested looks blown out.  When you go to pick the bulbs, do not just rip dem off of the plant.  Instead, twist dem first so they pinch de stem closed. It will keep de fluid from draining out.", objectives = "Plant 10 Riverbud Seeds in rivermud.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[51231] = { id = 51231, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wiccaphobia", description = "Do you see that... that shape up in the brambles up ahead? Is that... <Eitrigg shudders.>\n\nIs that goblin... wrapped up in that tree?", progress = "Huh?", completion = "I TOLD you I've got a bad feeling about this place...", objectives = "Investigate the shape up ahead, then protect Eitrigg and Gallywix.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[51232] = { id = 51232, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hundred Troll Holdout" }
quests[51233] = { id = 51233, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "I Hope There's No Witches in the Mountains", description = "<Gallywix looks flustered after his ordeal with the crone.>\n\nYou know, ah... I think maybe we better set up our foothold somewhere else. Maybe, up in the mountains? You know, like... not here, where the witches are?", progress = "Yes, {name}?", completion = "This... this I can work with.", objectives = "Drive Eitrigg and Gallywix to the mountains.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[51234] = { id = 51234, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Krazzlefrazz Outpost", description = "I already did a bunch of the leg-work for settin' up our foothold. All we gotta do is finish deploying all the instant-base technology, and we'll be good to go here in Drustvar.\n\nWhy don't you go finish the base building. I'm gonna see if I can salvage any wolfercycle parts.", progress = "What?", completion = "There we go. That's real nice.\n\nAnd hey, look! Here come some fresh rocket troops!", objectives = "Use the goblin devices in Krazzlefrazz Outpost to build your foothold in Drustvar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[51238] = { id = 51238, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Abandoned in the Burrows" }
quests[51239] = { id = 51239, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Instructions Not Included" }
quests[51240] = { id = 51240, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "WANTED: Anchorface", description = "Kill the blasted shark that ate me legs! And me crew! And me boat - even the anchor!\n\nHe's been swimming around in the sea, looking for his next meal. Kill 'im.\n\nI've left a reward with Cesi Loosecannon if you do.\n\n<The poster is signed 'Captain Slagbolt'>", progress = "Oh, did you kill that shark that almost got Ole Slaggy?", completion = "Nicely done! Here's the reward Slagbolt left. When he comes in to port next he'll be glad to see that shark gone.", objectives = "Slay Anchorface in the waters near Anyport.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[51241] = { id = 51241, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Bear Witch Project" }
quests[51243] = { id = 51243, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Breaking The Food Chain", description = "De extra riverbud you planted has helped, but it has not been enough.  Some of de local beasts are consuming de riverbud before dey can mature. We need dese plants to germinate, or we could risk losing it entirely.\n\nThe largest group of young riverbud consumers are de jacunda. If we are going to give de riverbud a chance to survive dis, you will need to thin their numbers.\n\nDo dat and I will teach you everything I know about riverbud.", completion = "Thank you for putting de fish down. I do not regret dis action, as dey would have starved if de riverbud ran out, so at least dey had a quicker death.\n\nThe secret to riverbud is dat dere are additional bulbs in de root system. Just pull de plant by de vine firmly with steady pressure.", objectives = "Kill 12 Ravenous Jacunda.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[51244] = { id = 51244, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "What Rots Beneath", description = "Good job killin' Ateena and sendin' whatever dat construct was down ta da bottom of... whatever dis ting be.\n\nMe scouts be seein' Titan Keeper Hezrel marchin' down to sometin' called da Altar of Rot.\n\nNow dat we got rid of dat construct, we can be flyin' down dere ta see what Hezrel be up to. \n\nDis be best handled by you and me. Da princess be havin' business back in da city.", completion = "No time to waste. Area ahead exhibits immense corruption triggered by G'huun.\n\nScanners indicate corruption caused by leak within G'huun containment structure.\n\nMust push forward to contain leak. Cannot perform function alone.", objectives = "Find Titan Keeper Hezrel within the Altar of Rot.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[51245] = { id = 51245, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "I'm a Lumberjack and I'm Okay" }
quests[51246] = { id = 51246, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Wreckoning", description = "I can't believe any of them survived the wreck. We were told to prevent any survivors from gaining a foothold.\n\nThere are far more of them than expected. We need to weaken their forces.\n\nWell? What are you waiting for? An engraved invitation?", completion = "We have an infestation of Alliance. We've done what we can. I will need to message for reinforcements.", objectives = "Kill 10 Shipwrecked 7th Legion.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[51247] = { id = 51247, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Things They Carried", description = "We need to know more about these sailors before we report back.\n\nIdeally, we would invade their camp but there are too many for our small group to take on. Lucky for us, they are focused on their salvage operation over safety. See if you can find any intelligence on their leaders who are scavenging the derelicts.", progress = "What have you found?", completion = "Intelligence isn't always gathered from the most obvious things.", objectives = "Acquire intelligence from the Alliance.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[51248] = { id = 51248, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Productive Pests", description = "This jungle is a whole new habitat for creatures and critters. A shame we're here to deal with Alliance driftwood.\n\nI've got an idea and I think it's genius. Two words: Poison bugs.\n\nFirst, I need some bugs. Crawling and flying ones, just to be thorough for our test.", completion = "These are going to be great!", objectives = "Gather 5 bugs", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[51249] = { id = 51249, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Crabulous Feast", description = "The Forsaken didn't bring any food with them. I think they might be cannibals. At the very least, they don't need to eat!\n\nTeekay and I are going to starve out here! {name}, if you're not too busy, could you bring us something to eat?\n\nMaybe some fresh crab?", progress = "My stomach is rumbling already.", completion = "This will do nicely. Now all we need is some butter. And maybe some lemon.", objectives = "Gather 7 lumps of crab meat from the Derelict Hexopods.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[51250] = { id = 51250, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Buzz Off!" }
quests[51251] = { id = 51251, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Basement Dwellers", description = "Ever since the untimely passing of dear, sweet Lizzie, rest her soul, the pests have multiplied like crazy!\n\nIn recent days, giant spiders have begun crawling out of the cellar underneath the southern mill. \n\nNo one has been able to go down there, for fear of being wrapped in web and eaten alive!\n\nWould you mind squashing a few arachnids and collecting any silk you find?", progress = "If only Lizzie were still here...", completion = "We can all rest easier now that those spiders have been squashed.", objectives = "Collect 8 Spider Silk from the Cellar Crawlers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[51252] = { id = 51252, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kiro's Desert Flower" }
quests[51278] = { id = 51278, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lost and Forgotten", description = "We have seen firsthand the depravity that has taken hold of my former brethren. The time has come to put an end to it.\n\nThe path ahead is no doubt packed with Lord Stormsong's cultists and their soulwrought elementals. I will absorb their souls as they fall with the Dead Ringer, as you once did.\n\nHowever, there will be no release for these fiends... not this time. We will need them to pry open the final door to the Shrine.", progress = "This burden is ours to bear, but I am glad we do not bear it alone.", completion = "Mourn not for the fallen. We do what we must to save our people.", objectives = "Fill the Dead Ringer with souls.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[51279] = { id = 51279, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nazmani Cultists", description = "The rumors o' the blood trolls from back in Boralus don't line up with the letters from Captain Conrad.\n\nOpen to trade? Willin' to work with us against the Horde? Ready to teach us their magic?\n\nHogwash.\n\nOnly time worth spendin' with these evil trolls is time killin' 'em.", progress = "That chantin' noise won't leave my head, draenei.", completion = "Know that feelin' when somethin's amiss and ya can't quite figure it? It's exhilaratin'!", objectives = "Kill 15 Nazmani trolls in Koramar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[51280] = { id = 51280, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Offerings to G'huun", description = "Been watchin' these cultists with both good eyes.\n\nThose big glowin' jars o' theirs look important.\n\nOpened one up and it sent a shiver down me spine, but nothin' seemed worth the takin'.\n\nIf it ain't worth stealin', I guess it's worth smashin'.", completion = "Doesn't seem ta be much o' value out here in this cursed jungle. Why'd Captain Conrad think they were worth tradin' with?", objectives = "Destroy 8 Offerings to G'huun in Zul'Nazman.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[51281] = { id = 51281, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zul'Nazman", description = "Not sure if I like this Harry fella. He's growin' on me, though. Got some wild ideas about the blood elves, but he's not all bad.\n\nWhat were we talkin' about? Ah, right.\n\nCaptain Conrad. He said the Captain went to Zul'Nazman ta commune with the blood trolls there. Seems... less than well planned.\n\nLet's go see what there is to see, shall we?", completion = "I'm startin' to believe we're on a corpse run here. Can't imagine we'll find the famous Captain Conrad alive at this point.", objectives = "Meet Brann Bronzebeard at Zul'Nazman in Nazmir.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[51282] = { id = 51282, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Captain Conrad", description = "Looks like there's couple o' guards posted by this hut. If I had ta guess, Captain Conrad'll be in there.\n\nSomethin' still feels off about this place, though. Why don't ya go on ahead and I'll hang here in case things go south fast?\n\nI got yer back, {name}.", completion = "I was wondering when you would come for me. I must admit that I am not as captive as you might believe. Quite to the contrary, in fact.", objectives = "Meet with Captain Conrad at Tul'vor in Nazmir.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[51283] = { id = 51283, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Voyage to the West", description = "Reconnaissance reports that the Horde has made inroads into the desert of Vol'dun.\n\nWe can't allow the Horde to continue to work there unchecked, so we're preparing an expedition to establish a beachhead.\n\n{name}, as one of our most accomplished soldiers I'd appreciate if you joined us. Your help will be essential for the success of our mission.\n\nWrap up your affairs here in the harbor and report to Grand Admiral Jes-Tereth. We will set sail when you're ready.", completion = "I hope the trip didn't make you seasick, {name}. Our mission is only just getting started.", objectives = "Speak with Grand Admiral Jes-Tereth and travel to Vol'dun.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[51284] = { id = 51284, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Falcon Hunt" }
quests[51285] = { id = 51285, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Feeding Frenzy" }
quests[51286] = { id = 51286, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stop the Evacuation", description = "This is a complete disaster. The intelligence you gathered seems to indicate that they already have footholds on this island and this is just another one.\n\nThey have a boat and we need to stall them. Here's some seaforium. Plant it on their boat and sabotage their hopes of escape. If possible, take out their Captain leading the evacuation.", progress = "I hope you have good news for me. For once.", completion = "Finally something goes our way. We've stopped them escaping, for now.", objectives = "Stop the Alliance evacuation efforts.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[51287] = { id = 51287, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tol Dagor: Sealed Supplies" }
quests[51296] = { id = 51296, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tol Dagor: The Overseer's Pride" }
quests[51297] = { id = 51297, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tol Dagor: Shorefront Property" }
quests[51302] = { id = 51302, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Underrot: Sealing G'huun's Corruption", description = "Massive leak of G'huun corruption located nearby. Substance surrounding us indicator of G'huun corruption, named underrot.\n\nInitial scans suggest a massive abomination composed of underrot is ahead, releasing more corruption into Nazmir.\n\nMust destroy Unbound Abomination, contain G'huun's corruption.\n\nFunction clear. Proceed inside.", completion = "Hezrel be dead? Dat be a shame, dat thing was useful ta have around. \n\nIt be good dat we stopped dis abomination in dere... but I be worried dat dis ain't gonna be da end.\n\nWe still gotta take down da construct dat we shot down... and hopefully find a way ta keep G'huun sealed.", objectives = "Enter the Underrot and defeat the Unbound Abomination.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[51305] = { id = 51305, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jelly Clouds" }
quests[51308] = { id = 51308, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zuldazar Foothold", description = "King Wrynn passed along orders to dispatch our finest to establish a foothold in Zandalar. That means you.\n\nFortunately, we have a few choices as to where we can set up camp.\n\nStick around. I'll go over the battle plan.", completion = "Backups from Kul Tiras? Perfect. I was just about to finish another execution.", objectives = "Listen to Commander Wyrmbane's battle plan, then speak with Grand Admiral Jes-Tereth to travel to Talanji's Rebuke in Zuldazar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[51309] = { id = 51309, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rocks of Ragnaros", description = "With me shaman still in their conveyances, a vital component o' our upcomin' ritual remains scattered among the supplies.\n\nI can only hope the Horde haven't taken 'em. They're rare an' precious...\n\nIf you see any glowin' objects out there, recover 'em. They're o' tremendous value.", progress = "I wasn't worried about 'em bein' broken. A little fire'd never hurt those rocks.", completion = "Couple o' scorch marks here an' there, but nothin' out o' the ordinary. These'll do nicely.", objectives = "Recover 9 Firelands Slag from the beach in Xibala.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[51310] = { id = 51310, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Raiders of the Lost Crop", description = "I could use a hand here!\n\nSo there I was, mindin' my own business and collectin' my harvest when these big galoots show up on their wolves and start torching the town! Luckily I was delivering a sack o' grain, or they'd have caught me and run me down!\n\nI won't stand for having these orcs or their dogs chewing up my fields or my crop.\n\nWhat do you say, friend? Help a farmer run some looters off his land?", completion = "Hah, that'll teach them to come here with their pooches and steal our grain!", objectives = "Slay 6 Orc Raiders.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[51311] = { id = 51311, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Energizing Extract" }
quests[51312] = { id = 51312, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aromatic Pollenator", description = "While gathering the pollen, you found a dead bug absolutely covered in pollen.  You know that this little creature is the secret to harvesting pollen easier, but the answer seems just out grasp.\n\nMaybe if you ask Declan about it, he might have an idea.", completion = "Oh, wow.  Yeah, that little fella is certainly covered in pollen.  Actually, this gives me an idea... but you may not like it.", objectives = "Bring the Dead Pollen-Covered Bee to Declan Senal.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[51313] = { id = 51313, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Learn From the Best", description = "You want to learn how these bees are so good at harvesting pollen, but if you show up, they'll start swarming you.\n\nWhat you've got is a problem that can be solved with a little alchemy.  I just so happen to have this potion that, once drunk, will turn the imbiber into a plant.\n\nHere's the deal: you go out and drink the potion, and you'll see firsthand how the bees do what they do. After the potion wears off, you tell me what happened.\n\nOh, and don't ask why I have that potion on me.", completion = "Fascinating!  It sounds like they used their bodies to block the mouth of the flower and beat their wings to stir up the pollen.\n\nWith the pollen being trapped inside the flower, it has no where to go but to get stuck on the bee.\n\nHmm, next time you've got a siren sting, try placing your hand over most of the mouth of the flower and gently blowing into it.  That might replicate what the bees were doing.", objectives = "Drink Declan's potion and allow bees to harvest your pollen.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[51314] = { id = 51314, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grain Drain", description = "We've got to salvage what we can.\n\nThis valley is the breadbasket of Kul Tiras. We feed the citizens, the militia, the army, you name it! Perhaps you've heard of our famous Kul Tiran sourdough bread? Goes great with sausages.\n\nMore importantly, those blasted Horde are getting in the way of our harvest! Lucky for us, the golems work 'round the clock to package the grain.\n\nI just need you to go out to the fields and grab as many bags as you can carry. I'll pay you for your trouble, of course.", progress = "We need that grain!", completion = "Good harvest this year. Our people will eat well.", objectives = "Collect 8 Sacks of Grain.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[51315] = { id = 51315, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wild Flutterbies" }
quests[51316] = { id = 51316, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Walking in a Spiderweb" }
quests[51317] = { id = 51317, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grounding the Grimestone" }
quests[51318] = { id = 51318, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Go for the Boat" }
quests[51319] = { id = 51319, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Final Ascent", description = "Beyond this gate lies Lord Stormsong... and our retribution. It seems he has sealed it tight, likely to buy himself time to finish whatever foul ritual awaits us.\n\nRelease the souls within the Dead Ringer when you are ready. I will direct them into the binding holding the gate shut.\n\nFrom there, we find Stormsong and end this once and for all.", progress = "No matter what lies beyond that gate, we face it together.", completion = "I thought this moment would never come.", objectives = "Open the Tempest Gate.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[51320] = { id = 51320, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sealed Fate", description = "Three wards ahead threaten to block our entry into the Shrine. We call them the Tidemother's Wrath, Radiance, and Pride.\n\nLegends say the wards were gifts from the sea itself. They once protected our flagships against even the fiercest storms. Ever since we settled here they have instead kept the Shrine of the Storm safe.\n\nIt seems Lord Stormsong has turned their power against us. I can feel their energy radiating out even from here, protecting his forces from our magic.\n\nWe must destroy them.", progress = "So long as the wards hold, we will be no match for Lord Stormsong's power.", completion = "I can feel the wards' power waning even now. This is our chance to strike.", objectives = "Destroy the Tidemother's Wrath, Tidemother's Radiance, and Tidemother's Pride.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[51322] = { id = 51322, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wings and Stingers" }
quests[51330] = { id = 51330, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Resilient Seeds" }
quests[51331] = { id = 51331, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mole Machinations", description = "Seems the enemy's anticipated our moves. While we developed our refinin' techniques for Azerite, the goblins 'ave done the same.\n\nIt wasn't five minutes after we established ourselves here that the Horde arrived to disrupt our progress.\n\nWe've got several shaman of great import waitin' impatiently in the mole machines on that beach.\n\nYou can take the key and clear the way so they arrive safely.", completion = "If they didn't wanna cook in a mole machine, they shoulda chose a different profession!", objectives = "Free 4 Dark Iron Earthbreakers from mole machines in Xibala.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[51332] = { id = 51332, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Trip Across the Ocean", description = "I understand you are to be establishing our foothold in Drustvar. You will be assisted on this mission by Trade Prince Gallywix.\n\nI know, a strange choice, but I am told that there is Azerite in Drustvar, and the Trade Prince was insistent.", completion = "Hey {name}. You ever been to Drustvar?\n\nWe're goin' to Drustvar.", objectives = "Report to Trade Prince Gallywix in Zuldazar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[51333] = { id = 51333, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Anchors Aweigh!" }
quests[51335] = { id = 51335, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cookies and Cream", progress = "Just a moment...", completion = "What did you think {name}, hit the spot, don't they?", objectives = "Enjoy Marie's fresh baked cookies and milk.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[51339] = { id = 51339, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cleaning Bills", description = "The Venture Company contaminates our pristine waters with toxic oil.  \n\nMy people are strong and will endure this until the time is right to strike back. The creatures with soft skins cannot wait. We must act now and save them from this danger.\n\nCollect and scrub clean any oily sandbill pipers you see. Quickly, before it's too late!", completion = "These smallest of victories are the foundation for the Venture Companies defeat.", objectives = "Clean 8 Oily Sandbill Pipers", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[51340] = { id = 51340, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Drustvar Ho!", description = "Azerite's in the air, {name}. Can ya smell it?\n\nDrustvar--way over in Kul Tiras--apparently has a real big seam o' Azerite beneath it. Azerite means profit, and profit means winning this war against the Alliance... which means even more profit.\n\nWe gotta get that Azerite!\n\nCheck in with Eitrigg an' Tattersail so we can get going soon. Time is money!", completion = "Here we are. Time to see what the Alliance is up to.", objectives = "Speak with Eitrigg and Dread-Admiral Tattersail.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[51341] = { id = 51341, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Daughter of the Sea", description = "They're not letting us any closer to the keep. We'll have to walk from here.\n\nReturning to Boralus has stirred feelings I thought I'd left behind. Memories smoothed away by the years like stones in the tide.\n\nIt all feels raw again.\n\nI do not know how this will end--only that we must try.", completion = "Hope you had a nice nap. You're gonna need your strength.", objectives = "Accompany Jaina Proudmoore to an audience with Katherine Proudmoore.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[51342] = { id = 51342, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Battle for Stromgarde" }
quests[51343] = { id = 51343, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Swimming Lessons", description = "For millennia we have roamed Azeroth's depths, yet never has a land walker journeyed with us. In order to help us, you must learn to travel the waters as we do.\n\nThe three scrolls of the sea shall grant you the energies to travel and survive underwater as we do.\n\nBring me the Scrolls of Harmonious Fins, Endless Tides and Graceful Breaths.", progress = "You must collect the Scroll of Harmonious Fins, Endless Tides and Graceful Breaths.", completion = "These will do nicely.  Just as we are, you shall now be one with the sea.", objectives = "Collect the three scrolls.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[51344] = { id = 51344, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To Matters at Hand", description = "Ye need te get back te Zuldazar, Princess Talanji's people are in desperate need of help.\n\nNow that ye got the heart, ye can absorb Azerite from all kinds of sources.\n\nUse the teleporter pad behind ye te return te Zuldazar. I be disablin' it when yer done... no need te have the likes of Nathanos walkin' in here.\n\nJust remember. Ye got the Heart of Azeroth around yer neck. Whatever happens... we must save the planet.", completion = "Good, you have returned. Dere is no time to waste.", objectives = "Use the Teleport Pad to return to Zuldazar", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[51349] = { id = 51349, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Honor Bound", description = "Sergeant Ermey is a man of honor, he would never leave one of his men behind. But one of these days that sentiment is going to get himself killed. \n\nWe don't even know what threats we face in this land. We certainly don't have the resources to spend searching for a missing private.\n\nI want you to go after him. Do whatever it takes to give up this fool's errand and return to the camp. He was last seen headed to the south-east, I'd start your search there.", completion = "Wyrmbane sent you after me, huh? Well, he's going to have to wait.\n\nThis thing knows where Private James was taken!", objectives = "Find Sergeant Ermey in Vol'dun.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[51350] = { id = 51350, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unexpected Aid", description = "I was shadowing those sethrak when I saw this one left for dead beside the trail. I don't think he's like the others. Looks like they roughed him up pretty bad.\n\nI made contact and before he passed out he said he knew where our man was being taken!\n\nWe need to find out what this thing knows!\n\nI'll need to make a salve for these wounds. There's some cactus I saw growing around here that should make a good base for it.", progress = "Got the cactus for the salve?", completion = "Those will do the trick!", objectives = "Harvest 8 Prickly Pear Roots in Bonetrail Gulch.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[51351] = { id = 51351, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Poisoned Barbs", description = "I'm surprised this snake-man is alive, let alone able to speak. Look at this! \n\n<Ermey holds up a needle-like barb.>\n\nIt looks like it came from one of those giant insects wandering about in the bottom of the gulch. I'll bet my stripes it's poisoned.\n\nYou know what they say, that which kills can also cure.\n\nGo get a few more of these barbs. I bet if I mix it in with that cactus he's wanting we will get a good antivenom to treat his wounds.", progress = "Got those barbs for me?", completion = "That's the stuff! Hope you didn't get stung too.", objectives = "Collect 8 Saltspine Barbs in Bonetrail Gulch.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[51352] = { id = 51352, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Don't Play with Matches", description = "These Venture Co. thugs set flame to the very oils they harvest. They hope to drive us from this land.\n\nTheir plan has a flaw. If a great wave extinguished every torch, their oil could not be lit. You can be our great wave!\n\nExtinguish all the flames here, and we shall be victorious this day.", progress = "Get to work, the battle is not won yet!", completion = "The war has just begun, but it was a great first victory!", objectives = "Eliminate 10 Venture Co. Flame Starters and 2 Venture Co. Oilers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[51353] = { id = 51353, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cave of Ai'twen", description = "Toki has researched a strategy that is historically sound. However to defeat the Venture Company, we will have to awaken Ai'twen from the bubble of tranquil waters.\n\nSeek out Loroja in the Cave of Ai'twen and we shall begin the process.", completion = "Your presence here can only mean one thing.  Ai'twen's help is needed.", objectives = "Seek out Loroja in the Cave of Ai'twen.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[51354] = { id = 51354, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Anger in a Bottle", description = "These quilboar are tougher than normal and I think I found out why.\n\nThey carry vials of some sort, filled with this nasty orange liquid. They'll quaff it and gain tremendous strength and stamina.\n\nI'll bet if we get some of it Hobbs could whip up a counter-agent, or whatever it is that alchemists do. Either way, deprive them of their strength potions and it'll make getting around here easier!", progress = "Do you have the samples yet?", completion = "This stuff smells awful. Maybe Hobbs will know what to do with it. Once we get out of here I'll make sure these samples get to him.", objectives = "Collect 10 Foul-Smelling Samples.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[51355] = { id = 51355, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Secretest Fish", description = "<Danielle Anglers in Mechagon may be interested in this fish.>", completion = "Where did you find this fish? It opens up many new possibilities for fish research!\n\nWith just a little adjustment, I can modify a rudimentary lure, adapting it to attract more fish than ever!\n\nOf course it might just attract more fishermen instead!", objectives = "Take the fish to Danielle Anglers in Mechagon.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[51356] = { id = 51356, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "WANTED: Sister Lilias", description = "The Waycrest Guard seeks an able-bodied soldier to eliminate a threat in Corlain.\n\nA witch by the name of Sister Lilias is wanted for the torture and killing of many of our townsfolk. Her end would prove a boon to all of Drustvar.\n\nPresent her head to claim your reward.", progress = "Inquisitor?", completion = "Ah, the witch is dead. Good.\n\nHere's your reward, as promised. Keep up the good work, Inquisitor.", objectives = "Collect Sister Lilias' head from Sister Lilias in Corlain.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[51357] = { id = 51357, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Armed and Ready", description = "You must be special if the sethrak didn't kill you right away.\n \nEither that, or you'd fetch a good price at the slave market.\n\nDon't worry though. We're getting out of here.\n\nI have a wagon at the entrance, but no weapon to fight with.\n \nLuckily, it seems the sethrak have plenty.", progress = "I'm good with whatever you pick, but let's hurry.", completion = "Using their own weapons against them. I like it.", objectives = "Choose a weapon for Nisha.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[51358] = { id = 51358, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "WANTED: Gryphon 'Nappers", description = "A warning to all gryphon owners!\n\nDo not let your feathered companions out of your sight. We have received numerous reports about gryphons in the area being stolen in the night.\n\nIf anybody can track down and stop these thieves, a reward awaits!", completion = "I heard the lost gryphon came back!\n\nI guess we've got you to thank, {name}.", objectives = "Kill Lindel the Snatcher and Silent Boris.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[51359] = { id = 51359, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fragment of the Firelands", description = "The rumors o' yer capabilities seemed overblown, but it appears yer indeed a competent one, aren't ye?\n\nI underestimated ye, {name}. For that, I apologize. Don't tell Thaelin.\n\nThe components for the ritual are now prepared. All ye need to do is add the Firelands Slag to the Unstable Magma an' a great bein' from the Firelands will heed our call.\n\nYou'll gain control o' it and can eliminate the nearby goblin threat with nigh invincibility.", progress = "Me shaman are gettin' better at this, aye? First couple o' summons and we had a hot fight on our hands.", completion = "Ah haha haaaaaaaaaaaa! Wow! I gotta admit, I'm a bit jealous I let ye take 'er out for a spin before I could. Those goblins never saw ye comin'!", objectives = "Stabilize the Unstable Magma then use the Magma Elemental to defeat 200 Bilgewater Goblins.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[51360] = { id = 51360, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Enormous Anchor Pod", description = "In all the gathering you've done, you have never come across an anchor pod of this size. Whatever the reason that it has gotten so large, there is much that can be learned from it.\n\nYour mind wanders back to Declan, and if there is anything about it in the book you picked up earlier.", completion = "Oh dear... This certainly appears larger than usual. Even the book does not have anything on a giant seed pod. This could be bad...", objectives = "Bring the Enormous Anchor Pod to Declan Senal.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[51361] = { id = 51361, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "More Anchor Pods", description = "Everyone in Kul Tiras knows that anchor weed is a blight that was brought here by merchants.\n\nIt thrives in this weather and it leechs nutrients from other plants, so we work to keep it from spreading, but it also has a strong magical essence, keeping us from just eradicating it.\n\nHowever, if it has mutated so it can disperse more seeds, we may need to finally purge it.\n\nBring me the biggest seed pods you can find, we need to see if this is a unique case. I'll dissect this one and learn what I can.", progress = "If the anchor weed is mutating, we may need to purge it from this land.  Do you have the other seed pods for comparison?", completion = "These all look reasonably sized, which helps to confirm my suspicions.\n\nWhile I was dissecting the enormous pod, I found glass splinters and noticed that the interior had an alchemical smell. It sounds crazy, but I think an adventurer dropped an elixir of giant growth, shattering the vial and this plant soaked it up.\n\nThe enlarged anatomy of the giant pod let me notice that these thick walls of the seed pod are actually thin and lined with additional seeds!  You can peel the pod for more seeds!", objectives = "Harvest 9 Mature Anchor Pods from anchor weed.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[51364] = { id = 51364, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An Explosive Exit", completion = "This is the troll you flew in with, is it not? She lives, for now.", objectives = "Find Nisha's wagon and ride it to safety.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[51365] = { id = 51365, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cultural Significance", description = "I've noticed your skill with harvesting plants has improved, but I also noticed that you just treat each flower and leaf as a commodity.  The flora of these islands have a rich history, with a deep cultural significance to us.\n\nTake this sea stalk, go around town, and ask some of the men and women what it means to them.  Humor me, and I'll make it worth your while.", completion = "Sea stalk has a unique magical property that allows the stalk to provide the flower water, even if the flower is cut off. \n\nSailors will give their loved ones a flower and keep the stalk on themselves, so if they fall over board, the salt water kills the flower. What you hold is more than a stick, it's a family member's life.\n\nAs for your lesson, unlike most other magic plants, the best material to harvest for magical essence is the stem, not the leaves or flower.", objectives = "Learn the importance of sea stalks from people in Boralus.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[51366] = { id = 51366, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Antidote Application", description = "The antidote's ready. \n\nIt smells like death and tastes worse, but it should be potent enough. Let's hope that we're not too late for it to do any good.\n\nHere, administer the salve to his wounds. It should work nearly instantly.", completion = "I can feel life returning to my limbs. Thank you, stranger!\n\nI'm afraid we don't have the time for more of an introduction. Your friend is held captive by the Faithless.\n\nDon't worry, my people will be happy to aid you in return for your kindness to me.", objectives = "Administer the Antivenom to Vorrik.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[51367] = { id = 51367, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "WANTED: Raging Earthguard", description = "Be careful when traveling toward Anglepoint!\n\nAn immense creature of the earth has spawned on one of the hills, threatening all who go near.\n\nAny adventurers who take down this earthen guardian shall be rewarded greatly.", completion = "You defeated the revenant! Bully! Well done as always, my friend!", objectives = "Kill the Raging Earthguard west of Norwington Estate.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[51368] = { id = 51368, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "WANTED: The Hornet", description = "That's it, I'm putting a bounty on that blasted hornet.\n\nEvery time I try to do some good old fashioned bare-handed fishing, that son of a bear comes after me.\n\nSomebody take that bug down!", completion = "The hornet's dead! Good on ya, house cat.\n\nI'd like to not die to a bug.", objectives = "Kill The Hornet.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[51369] = { id = 51369, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Friends in Strange Places", description = "I saw a creature like your friend here. We both were being held captive by my ruthless kin, the Faithless.\n\nBefore I was cast aside I gave him something to protect, something most precious. Naturally, I would also like to see your friend's safe return.\n\nMy people will lend you their aid.  Come, I will call for my pterrordax to take us. Together we shall find where your soldier friend was taken.", completion = "Oh no! The Faithless are attacking the temple!", objectives = "Fly to the Sanctuary of the Devoted.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[51370] = { id = 51370, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Short-Supply Reward" }
quests[51371] = { id = 51371, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flavorable Offering", description = "Ai'twen saved many Tortollans during the great purge of the Inky Grotto. He rests here in this tranquil bubble as a reward for his service.  To entice him back to our world we'll need a flavorful offering.\n\nThe seaweed that grows outside is Ai'twen's favorite meal. Its salty flavor will surely coax Ai'twen to leave the bubble for our world. Gather it from the creatures outside this cave, and where it grows wild on the reef.", progress = "Search for the Seaweed outside and on Makrura Brineshells", completion = "An excellent offering.  Let us watch now, and see if this will suffice.", objectives = "Gather 50 Seaweed.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[51373] = { id = 51373, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ears Everywhere" }
quests[51374] = { id = 51374, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unending Gorilla Warfare" }
quests[51376] = { id = 51376, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Can't Teach on an Empty Stomach", description = "I would love to teach you, but it's so hard for me to concentrate right now.  I haven't eaten anything all day, so it's all I can think about.\n\nHowever, if a helpful adventurer were to fish up some lane snapper from the ocean just behind me, I would owe them a something in return.  Perhaps something valuable, such as advice in regards to effectively picking the notorious winter's kiss.\n\nIf you don't feel like fishing, you could just buy some on the auction house, I don't mind.", progress = "Oh, do you have something for me?", completion = "You brought me fresh fish? What a wonderful surprise! Now I can focus on teaching an eager pupil.\n\nThe important thing to know when trying to pick winter's kiss is that any exposure to heat before it is harvested can cause the flower to wilt.\n\nTo prevent that from happening, bury your hands in the snow right before you harvest it. By reducing the temperature of your hands before touching the plant, you can usually get a couple extra petals without issue.\n\nGood luck!", objectives = "Collect 7 Lane Snapper for Xun Xun Sweetflower. Lane Snapper can be fished from the ocean or purchased from the Auction House.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[51377] = { id = 51377, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Temple of Sethraliss: Ecological Research" }
quests[51378] = { id = 51378, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Temple of Sethraliss: A Bazaar Menagerie" }
quests[51379] = { id = 51379, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Temple of Sethraliss: Navigating Currents" }
quests[51380] = { id = 51380, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Back to Franklin", description = "Oh, good! You are still here!\n\nI heard you had built a rapport with Franklin. I'd be lying if I said talking about him didn't make me reminisce when we worked together.\n\nIf you're not busy, could you go talk to him? Ask him if he can show you anything else. I'm sure he remembers more, if you're still looking for more information.\n\nAnd tell him that if he were to get his life sorted out, I'd like to talk to him about working together again.", completion = "Myra sent you?\n\nWait... my old business partner?", objectives = "Speak with Franklin The Drunk.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[51384] = { id = 51384, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "WANTED: Quartermaster Ssylis", description = "Don't venture too far into the bay if you're not looking for a fight!\n\nA couple of Bilge Rats have taken up residence in a nearby cave, and they won't stand down from any challenge.\n\nThey ain't harming anybody, 'long as you stay away. But if somebody wants to go take care of their leader, they will be rewarded.", progress = "<Alby nods at you.>", completion = "Aye, you got the saurok.\n\nBilge Rats should be out of here soon enough.", objectives = "Kill Quartermaster Ssylis in Krakenbane Cove.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[51385] = { id = 51385, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Supply of Stingers" }
quests[51386] = { id = 51386, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Battle Victorious", description = "We have everything necessary to strike a blow against this Venture Company. \n\nOur plan is sound, we are well prepared and we have the element of surprise.\n\nWe shall ride atop Ai'twen and reign chaos upon them with their very own weapons.", progress = "The Venture Companies defeat is at hand.  Let's get to it!", completion = "This victory will be discussed for millennium to come.  The Venture Co. is a resilient foe though, I am sure we will meet them again!", objectives = "Ride Ai'twen and destroy the Venture Companies forces", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[51388] = { id = 51388, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stopping the Infestation" }
quests[51389] = { id = 51389, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Breaking Free", description = "Look, these guys are in a tough spot but let's not lose track of the mission. We've got to rescue Private James!\n\nI saw a bunch of cages down in the camp of those snakes that are besieging the temple. If James is going to be anywhere, then it'll be there!", completion = "I can't believe you and the sarge went to such effort to rescue me! I'm... I'm speechless... thank you!", objectives = "Find Private James and free him from his captors.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[51390] = { id = 51390, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "WANTED: The Crimson Cutthroats", description = "For numerous and sinister crimes against the Lord Admiral: smuggling, forgery, sailing under false colors, looting, poaching, brigandage, sacking, pillaging, vandalism, impersonating Kul Tiran Naval officers, arson, kidnapping, torture, piracy, perjury, theft and ransacking multiple mead shipments.\n\nA reward is placed on the heads of The Crimson Cutthroats to be paid in full upon proof of their demise.", completion = "You finally got those damnable outlaws? Well done! My people have enough trouble here without having to deal with brigands. \n\nTake your reward with my thanks.", objectives = "Slay the Crimson Cutthroats near Falconhurst.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[51391] = { id = 51391, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Defang the Faithless", description = "Did you see them as we flew in? The Faithless are sieging the temple! \n\nFriend, I know we just met but I must ask for your aid once more. Please, help us break their ranks!", completion = "I've already heard how you sent the Faithless running! \n\nOn behalf of my people, thank you.", objectives = "Kill 12 Faithless attackers within the Temple Grounds.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[51394] = { id = 51394, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Break the Siege", description = "This isn't the first time the Faithless have attacked us, nor will it be the last, but the temple must be protected!\n\nPlease, do whatever you can to destroy their siege equipment and push them back.", completion = "The Faithless will never stop their siege, but your efforts have bought us time.", objectives = "Disrupt the Faithless assault on the Sanctuary of the Devoted.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[51395] = { id = 51395, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Keepers' Keys", description = "It's good to see that your companion is back unharmed.\n\nBut more importantly, let's see if he still has my stone hidden in his pockets.", completion = "The Faithless will never stop their siege, but your efforts have bought us time.", objectives = "Speak to Private James and uncover the significance of Vorrik's Stone.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[51397] = { id = 51397, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Up In Your Drill", description = "<The drill on the front of the machine is in good condition.>\n\n<This seems like the perfect type of work hazard.>", objectives = "Use the Goblin Mining Machine to disrupt the excavation camp.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[51398] = { id = 51398, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An Unusual Mentor", description = "Hey {name}, you look like you're ready to handle hostile territory.\n\nFar away in the desert of Vol'dun, on the continent of Zandalar, there grows a plant called akunda's bite. You couldn't pay me enough to go there myself, and there's almost no mention of them in any of the books I've read, but all is not lost.\n\nI know of an herbalist who lives there in the desert and studies that plant.  Find him, and I'm sure he'll be able to teach you a thing or two. Oh, and do be warned...\n\nHe is a bit... eccentric.", completion = "You seek knowledge on akunda's bite? Marvelous plant, but surprisingly delicate given the harsh environment. Only the strongest will survive...\n\nHmmm... Yes, you'll do nicely.  If you assist me in my work, I would be willing to provide you with some insights.", objectives = "Find Patu in Vol'dun.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[51399] = { id = 51399, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Foul Harvest", description = "You have traveled far to find knowledge, but you have found me instead. I am curious though, how much further you would travel for it. I will teach you, if you do something for me first.\n\nIron sharpens iron, as they say, so too does adversity strengthen the seed.\n\nGo out and find seeds, ones that have been consumed by the wild beasts and have returned to the earth unscathed.\n\nOnly those seeds will be strong enough to survive the desert sands of Vol'dun.", progress = "Were you able to get the seeds?", completion = "Hmmm... This seems like a good harvest. There is a quiet dignity in their resilience.\n\nBut dignity is not enough. They must be more than quiet, they must quake with thunder.", objectives = "Collect 12 Digested Akunda's Bite Seeds.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[51401] = { id = 51401, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Carry On", description = "Let's get to Brennadam right away. We need to find Brother Pike and get to the bottom of all of this before things get any worse.\n\nThis road should take us right into town. Brennadam's the busiest market this side of Boralus, so there should be plenty of people there who can help us find Pike.\n\nReady when you are!", completion = "Looks like more trouble.", objectives = "Meet Taelia in Brennadam.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[51402] = { id = 51402, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reporting In", description = "I can't believe what we got ourselves in the middle of here. Keystones, C'Thraxxi, there's even a snake-man civil war going on!\n\nAll I know is Wyrmbane is going to want a full report and if there's anything I hate more than inept privates getting themselves captured it's paperwork.\n\nLet's get going.", completion = "<Wyrmbane listens to your report.>\n\nThe news of this C'Thraxxi is troubling, but you did well in befriending the local population. This likely won't be the last time we'll have to depend upon them.\n\nWell done, {name}.", objectives = "Report to High Commander Halford Wyrmbane.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[51403] = { id = 51403, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Speaker's Imperative", description = "The world's soul is secure... fer now. I can hear Azeroth again, although her voice is still weak.\n\nThe elementals on the surface above have calmed down. Even using just a fraction of its power, the Heart of Azeroth brought stability tae this place.\n\nYe need tae return tae Stormwind and inform your allies of what transpired here. Remind them that no matter what happens with the Horde, our world must be saved.\n\nWe'll speak again soon, {name}. The battle fer Azeroth has only just begun.", completion = "<Wyrmbane listens to your tale.>\n\nThe Heart of Azeroth... a powerful artifact indeed.  Thank the Light you were there to aid Magni.\n\nBut I fear I bear dire news, {name}. While you were away, the Horde launched a brazen attack on Stormwind.\n\nI have a message for you from King Anduin. You must meet him at the keep at once.", objectives = "Return to Stormwind City.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[51404] = { id = 51404, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "What Happens Next", description = "After feeling the bite of Akunda so many times, static electricity causes your hair to stand on end as you hold in your hands an intact lightning pod. You noticed that by wrapping the lightning pod in it's own leaves, you were able to remove it without discharging it.\n\nIf you manage to develop this technique, harvesting this plant would become significantly less hazardous and provide additional material in pristine condition.You will learn:", objectives = "Harvest 10 Akunda's Bite without being shocked.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[51405] = { id = 51405, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Corruption in the Bay" }
quests[51406] = { id = 51406, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Lord's Hunt" }
quests[51407] = { id = 51407, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Find Their Words", description = "This portal will get you quickly back to the outpost.\n\nWhen there, present the orders to Akru. \n\nHer knowledge is vast, she will be able to discern the truth within.", progress = "Ah. Deyon is correct. I know many things. What do you have there?", completion = "Yes... yes... I see here. Dire words indeed, young one.", objectives = "Deliver the Orders from Nazjatar to Akru at Seekers' Outpost.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[51408] = { id = 51408, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Giving Back to Nature", description = "Perform one additional task, and I will give you the knowledge you seek. The seeds you have are strong, but they need time until they are ready to grow. \n\nHowever, one must always be prepared in the desert. This sapling is mature enough to live on its own, but it is frail. It needs the dry desert winds to build static so it may bite, but until it does, it is as helpless as grass.\n\nPlant it in the desert sands, near the fallen beast south of the Brine Basin, and protect it until it can defend itself.", progress = "Have you planted the sapling yet? Has it taken root?", completion = "Your efforts have been instrumental in maintaining the balance in this land.\n\nNow I shall reward you with the knowledge you sought... But first, when you approach the flower, what do you do?\n\n<Patu nods as you explain your current knowledge of harvesting akunda's bite>\n\nHmmm... It seems that you do not know  the value of this plant's leaves. The bulb discharges on touch, which will kill the leaves if they are still attached. Harvest the leaves first and your yield shall be greater.", objectives = "Plant the Akunda's Bite Sapling and defend it until it builds a static charge.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[51411] = { id = 51411, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Azerite Mining" }
quests[51412] = { id = 51412, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Azerite Empowerment" }
quests[51415] = { id = 51415, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Azerite Madness" }
quests[51418] = { id = 51418, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Xibala", description = "{name}! How's things going over here?\n\nOh. Wow. There's Horde soldiers everywhere. And Zandalari trolls. And hardly any machines at all.\n\nWe should DEFINITELY head back to Xibala, with the dark iron dwarves. It's perfect for our foothold!", completion = "You're {name}, the {race} {class} that Kelsey's been talkin' up? We've heard much about ye, lad.", objectives = "Use the rowboat in Talanji's Rebuke to travel to Xibala.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[51421] = { id = 51421, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shiver Me Timbers", description = "It seems our resident shadow hunter has managed to seize a small pirate sloop.\n\nWe have sent him to Tiragarde Sound in a search for a foothold, and it seems that he has concocted a plan.\n\nTy'jin has requested your help, personally. Do not keep him waiting.", completion = "Welcome ta Tiragarde, boss-mon. Ya ready to be parleyin'?", objectives = "Accompany Shadow Hunter Ty'jin to Tiragarde Sound.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[51422] = { id = 51422, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Azerite Madness" }
quests[51425] = { id = 51425, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "There's No Place Like Home", description = "So, the Arathi Highlands. Quite a sprawl, isn't it?\n\nAt some point, you may wish to return to this fair Stromgarde with haste.\n\nMight I offer a suggestion as to how...?", completion = "Should you desire to return with haste, simply use this, yes?", objectives = "Talk to Captain Roderick Brewston", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[51426] = { id = 51426, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Inspection Gadget", description = "Some time ago, a good friend of mine who had a tinker shop in Boralus just stopped all correspondence. With the state of foreign affairs, I wasn't able to look for him myself until recently.\n\nIt's not just him. It seems that all of the gnomes that were living in the city just up and vanished.\n\nI've decided to start my search with these ruins, but the machines here have gone haywire. Could you go get a good magnetic reading on the place?", completion = "This data is astounding! It will take quite a while to go through all of it.", objectives = "Survey the Rusted Vault.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[51427] = { id = 51427, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "I Like Turtles", progress = "We are patient.  When you are ready.", completion = "An excellent offering.  Let us watch now, and see if this will suffice.", objectives = "Present the offering to Ai'twen.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[51428] = { id = 51428, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Azerite Wounds" }
quests[51429] = { id = 51429, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "King Clickyclack" }
quests[51430] = { id = 51430, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reverse Tinkering", description = "The sentry bots here are definitely of gnomish make. If the creator had any sort of proper education, each machine should have some sort of serial code on it.\n\nAnd if they've been properly documented, I might be able to use those codes to track that gnome down.\n\nDo you think you could bring a few of them back to me?", progress = "Did you find anything interesting?", completion = "I'll have to send these back to Ironforge and we'll see if they can find anything.", objectives = "Gather 4 V-300 serial plates.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[51431] = { id = 51431, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Soul Goliath" }
quests[51432] = { id = 51432, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An Unusual Mentor", description = "You have done well so far, {name}, but dere is still much more for you to learn. I think it is time for you to meet an old 'friend'.\n\nDere is no better person I know of to teach you about akunda's bite, as his knowledge and respect for de plant is unrivaled.\n\nHead North beyond the desert of Vol'dun. Dere you will find a tortollan who will teach you more about de desert flower.", completion = "You seek knowledge on akunda's bite? Marvelous plant, but surprisingly delicate given the harsh environment. Only the strongest will survive...\n\nHmmm... Yes, you'll do nicely.  If you assist me in my work, I would be willing to provide you with some insights.", objectives = "Find Patu in Vol'dun.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[51433] = { id = 51433, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Matron Morana" }
quests[51434] = { id = 51434, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stone Golem" }
quests[51435] = { id = 51435, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Swashbuckling in Style", description = "First ting's first, boss-mon. Ya can't parley with pirates unless ya got da appropriate clothes.\n\nI ain't big on fashion, mon, but what ya be wearin' won't work.\n\nLuckily I collected dis box of pirate clothes. No need ta ask how. Just need ta get piratey.", progress = "Pick whateva ya want, boss-mon. Dere be so many clothes in dat chest.", completion = "Now we be talkin', boss-mon! Ya look ready ta do some privateerin'!", objectives = "Put on a pirate disguise from the chest of Pirate Garb.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[51436] = { id = 51436, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Parleyin' Wit Pirates", description = "Some a dese pirates be unhappy wit' da leadership.\n\nI been hearin' dey're da last truly free pirates. Da rest be sellin' out ta some lady named Ashvane.\n\nI don' really care 'bout dat, but da captain of dese Fogsail Freebootas  is tinkin' 'bout sellin' out too.\n\nWe gonna help stop it, and in return build a foothold here.", progress = "{name}, nicht wahr? Ich habe vernommen, dass Ty'jin einen Champion seiner Horde schicken würde.", completion = "I don't care about your faction wars, {name}. If you are the folks that will help save my crew, you are the folks that will get my help.", objectives = "Follow Shadow Hunter Ty'jin and meet First Mate Owings.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[51437] = { id = 51437, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spike the Punch", description = "Step one in causing a mutiny? Make it seem like leadership is incompetent.\n\nIf the captain wants to sell our souls to the Ashvanes, we're going to need to get dirty.\n\nI hate to say it... but we've got to muck up the booze.\n\nThat'll make the crew angry at the captain before you can even blink.", progress = "It's a dirty deed, but it's necessary.", completion = "That is not what I...\n\nYou know what? Sure. That works.", objectives = "Spike 6 Kegs of Grog.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[51438] = { id = 51438, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Marking Our Territory", description = "Dis could turn out ta be quite da foothold, boss-mon!\n\nI will help wit' da settlin', turnin' da place into a good base.\n\nI tink we need some spikes.\n\nLet's be makin' tings official.", progress = "Dis place be feelin' like home in no time.", completion = "Dis place be feelin' like home in no time.", objectives = "Plant the Horde Banner in Plunder Harbor.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[51439] = { id = 51439, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cannonball Collection", description = "Walkin' through da harbor gave me some ideas, boss-mon.\n\nYa see dem big guys wit' da cannonballs?\n\nCollect some a dat ammo and bring it ta me. I tink I be havin' a use for it.", progress = "Did ya get da cannonballs?", completion = "Oh da goblins gonna be lovin' dese, mon.", objectives = "Collect 3 Fogsail Cannonballs from Fogsail Cannoneers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[51440] = { id = 51440, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Change in Direction", description = "Whispers of dissent have been spreading through the harbor, {name}.\n\nYou can hear the grumblings of pirates who do not want to give up their freedom!\n\nRumor holds that some of the other authority figures have goals that align with mine.\n\nI forged some letters in the captain's hand. Deliver them... see who bites.\n\nOr who gets in our way.", progress = "Mutiny is about subversion. We must fly under the radar as long as we can!", completion = "I hoped that Taryn would see the truth. Ah, well. So it goes.", objectives = "Deliver the forged orders to Boatswain Taryn, Quartermaster Killian, and Navigator Swink.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[51441] = { id = 51441, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Thar She Blows!", description = "Our goblin engineers been workin' on modifyin' some cannons for our uses.\n\nDa cannonballs you been collectin' be perfect ammo for dem.\n\nDere are rowboats in da harbor dat be readyin' ta bring loot to Owings's enemies. Take dis cannon and sink 'em before dey can get away!", progress = "Sometimes ya gotta use da ammo of ya enemies against dem, mon.", completion = "Now we be havin' ourselves a mutiny!", objectives = "Use the Goblin-Engineered Hand Cannon to sink 3 Fogsail Rowboats.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[51442] = { id = 51442, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "I'm the Captain Now", description = "Alright {name}... It's time to take the mutiny to the captain.\n\nRhenik sits in his cave, readying himself to sell our souls to the Ashvanes!\n\nDefeat him, and I will allow you to use my port as though it were your own.", progress = "I cannot stand by and watch Rhenik sell our freedom.", completion = "Captain Owings...\n\nIt has a certain ring to it, don't you think?", objectives = "Kill Captain Rhenik.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[51443] = { id = 51443, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Battle for Azeroth: Mission Statement", description = "{name}! The Warchief has summoned you to undertake a mission of the utmost secrecy.\n\nThe very future of the Horde is at stake.", completion = "The Dark Lady has placed her trust in us. We will not fail her, {name}.", objectives = "Receive your mission from Warchief Sylvanas Windrunner within Orgrimmar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[51444] = { id = 51444, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Azerite Empowerment" }
quests[51445] = { id = 51445, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Thros, the Blighted Lands", description = "The Blighted Lands... \n\nIf the legends are true then inside we will witness suffering and torment the likes of which we have never known. ..\n\n...but if that is what I must endure to right what I have wronged, then I will cross that threshold gladly.\n\nWill you join me, {class}?", progress = "I'm with you, champion.", completion = "Words cannot express the debt I owe you for helping return my daughter to me, but unfortunately the traitor Ashvane has left us no time for celebration.\n\nWe must act.", objectives = "Find Jaina in Thros, the Blighted Lands.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[51446] = { id = 51446, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Meet Sweetflower", description = "You have seen and learned much from these islands, but Zandalar is not de only place where you can learn. I have heard of a flower dat cannot grow on dese islands.\n\nIf you want to know more about it, you will need to find someone more knowledgeable dan myself. Fortunately for you, I know of someone who may be able to help you.\n\nHer name's Xun Xun Sweetflower, and last I heard she set up shop on the outskirts of Anyport over on de human island of Drustvar.", completion = "Oh, you'd like to learn about harvesting winter's kiss?  Well that's very fortunate, for both of us...", objectives = "Find Xun Xun Sweetflower in Drustvar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[51447] = { id = 51447, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aromatic Pollenator", description = "While gathering the pollen, you found a dead wasp absolutely covered in pollen.  You know that this little creature is the secret to harvesting pollen easier, but the answer seems just out grasp.\n\nMaybe if you ask Jahden about it, he might have an idea.", completion = "Yes, I am familiar with dese wasps. Dey are notorious for how... Actually, this gives me an idea... but you may not like it.", objectives = "Bring the Dead Pollen-Covered Wasp to Jahden Fla.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[51448] = { id = 51448, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Learn From the Best", description = "You want to learn how these wasps are so good at harvesting pollen, but dey will defend their territory once you set foot inside it. Dis would be a problem, but I think I have a solution.\n\nTake dis potion and go to Vol'dun, to de Prickly Grove, and drink it to turn into a plant.\n\nHere's the deal: you go out and drink the potion, you'll see firsthand how the wasps do what they do. After the potion wears off, you tell me what happened.", completion = "It is good dat you experience dat first hand. It sounds like dey used their wings to stir up de pollen.  With dem being so close to de flower, de pollen had no where to go but to get stuck on the wasp.\n\nHmm, next time you've got a Swarma' Sting, try placing your hand over most of the mouth of the flower and gently blowing into it.  That might replicate what the wasps were doing.", objectives = "Drink Jahden's potion and allow wasps to harvest your pollen.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[51450] = { id = 51450, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Azerite Mining" }
quests[51451] = { id = 51451, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Disgustingly Damp Flower", description = "Rummaging for pollen as usual, you use the harvesting technique you learned from the wasps.  However, when you pull your hand away from the flower, you find that there is no pollen to be seen.\n\nLooking inside the swirl of petals, despite it being a mature flower, you see that there is no pollen at all.  Upon closer inspection you see that the flower is filled with a viscous liquid.  Could the flower have done this?\n\nWhile unpleasant to touch, you carefully pluck the flower to show Jahden.", completion = "Hmm... Dis flower does not seem to have any pollen left. I cannot say that I have heard of a plant doing that before. Dis must be the work of some other creature.", objectives = "Take the Disgustingly Damp Flower to Jahden Fla.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[51452] = { id = 51452, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pollen Punching", description = "It looks like some beast managed to lap up all de pollen with it's tongue. It is curious as to what creature could have done dis, I doubt it matters.\n\nYou should be able to do dis yourself without needing any sort of rare or dangerous reagents.\n\nNext time you find a siren's sting, wet your glove so the pollen will stick to it. Water, wine, blood... It should not matter.You will learn:", objectives = "Collect 12 Heaping Handfuls of Damp Pollen.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[51453] = { id = 51453, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shrine of the Storm: Behold, Pure Water" }
quests[51454] = { id = 51454, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Once More Into Battle" }
quests[51455] = { id = 51455, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shrine of the Storm: Cleansing Fonts" }
quests[51456] = { id = 51456, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shrine of the Storm: Crawling Corruption" }
quests[51457] = { id = 51457, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Whargarble the Ill-Tempered" }
quests[51461] = { id = 51461, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Deathcap" }
quests[51462] = { id = 51462, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Paratroopers" }
quests[51463] = { id = 51463, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sky Drop Rescue" }
quests[51464] = { id = 51464, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Here In Spirit", description = "If you are up to de challenge, I have a task dat I believe is up your alley.\n\nDe spirits of dis land are screaming out in anguish. However, dey are either unwilling or unable to talk to me in their current state.\n\nI need you to get some fresh star moss, which will help anchor and calm their spirits. Once dey are calm, we will be able to give dem de help dey need.\n\nDo dis, and I will teach you how to harvest star moss more effectively.", progress = "De spirits are restless. Have you managed to get de fresh star moss yet?", completion = "You have done well. I will begin the ritual as soon as I can.\n\nIn de mean time, you are owed a lesson on how to harvest star moss.\n\nThe magic of star moss is sensitive to emotions, which is why it helps ground those dat have passed on.\n\nWhen you go to harvest, clear your mind and think of those you've lost. Dat feeling of loss, reverence, and de joy dey once brought will keep de bloom from wilting.", objectives = "Collect 10 Fresh Star Moss.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[51465] = { id = 51465, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Load of Scrap", description = "Hey there stranger, you want the scoop on the latest invention of the century?\n\nIt's called the Shred-Master Mk1 and this baby can triple, no QUADRUPLE your production capacity as a crafter of armor, weapons or other doohickeys you adventurers wander around with.\n\nHere, take these pants and use the Shred-Master on 'em. You'll get the gist of it.", progress = "This machine is gonna change everything.", completion = "And just like that, you're back in business. All the materials you put into makin' the item come back to you with the Shred-Master Mk1.\n\nOkay, fine! Maybe not ALL the materials, but hey, something's better than nothin', right?\n\nOh, and keep an eye out for explusom. It's what we've discovered as a magical byproduct of the scrappin' process.\n\nIt's quite potent and only shows up when we scrap really fancy stuff.", objectives = "Use the Shred-Master Mk1 on the pair of Tattered Pants.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[51466] = { id = 51466, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arvon the Betrayed" }
quests[51467] = { id = 51467, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hyo'gi" }
quests[51468] = { id = 51468, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bonesquall" }
quests[51469] = { id = 51469, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Betsy" }
quests[51472] = { id = 51472, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Life Preserver", description = "The Thornspeakers were assisting me but they have troubles of their own.\n\nI came in search of a powerful dragon who fell in battle many centuries ago. Melting snows have revealed Vadekius's final resting place.\n\nMy Queen has tasked me with ensuring his body cannot be reanimated and enslaved. The ritual will require my full attention and my druid friends aren't fit for combat.\n\nWatch my back while I ensure my cousin's soul flies amid the branches of G'Hanir, safe from undeath.", progress = "Will you watch my back as I complete the ritual?", completion = "Thank you for your help.", objectives = "Protect Zallestrasza while she conducts the ritual.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[51474] = { id = 51474, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Forged in Fire an' Flame", description = "Ye've done more than I had any right tae ask, {name}. Recovered Ironfoe from our enemy, retrieved a fragment o' the Molten Core, an' exposed the enemy within our ranks at the Firelands.\n\nIf ye'd do me the honor, would ye come with us tae Blackrock Depths one last time while we repair our most sacred anvil?", progress = "Ye've been a lifesaver, {name}.", completion = "We're grateful to ye, {name}.", objectives = "Speak with Moira at the Stormwind Embassy to travel to Blackrock Depths and repair the Black Anvil.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[51475] = { id = 51475, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Brutal Escort" }
quests[51478] = { id = 51478, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ghost Busting", description = "I have spoken with de spirits. Most of dem were willing to bare their souls, calling for help from de living as dey are under attack from de blood trolls evil magic.\n\nDere was one, however, who seemed more angry dan most. It was furious dat we had not acted yet, dat we allowed things to get dis bad.\n\nGo to de Spirits Be With You inn at de port north of here and put dis spirit down, and in return I will teach you everything else I know about gathering star moss.", completion = "I owe you my thanks, {name}. Now that the spirit has been been put to rest, I can get back to work.\n\nYou have shown, once again, dat I can rely on you. In exchange, I will tell you the best kept secret of star moss.\n\nDis is going to sound crazy, but engage with it. Before you pick de flowers, talk to it, sing, hum, anything. I'm not sure why, but since I started, I have noticed one or two extra flowers will bloom before my eyes!", objectives = "Put the Angry Spirit to rest.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[51479] = { id = 51479, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Uncorrupted", description = "This world is... not what I expected.\n\nIt is time for us to meet your warchief, {name}.\n\nThere is no need to delay any further.\n\nWe can lick our wounds once we have a roof over our heads.", completion = "I see you brought a new face along with you, {name}", objectives = "Return to Ji Firepaw in Orgrimmar to hear the end of this tale.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[51480] = { id = 51480, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Enormous Anchor Pod", description = "In all the gathering you've done, you have never come across an anchor pod of this size. Whatever the reason that it has gotten so large, there is much that can be learned from it.\n\nYour mind wanders back to Jahden, and if there is anything about it in the book you picked up earlier.", completion = "Hmm... Dis certainly appears larger than usual, even de book does not have anything on a giant seed pod. I have a thought...", objectives = "Bring the Enormous Anchor Pod to Jahden Fla.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[51481] = { id = 51481, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "More Anchor Pods", description = "I need you to bring me a handful of mature anchor pods.\n\nYou see, dis seed pod is massive, but it is still just a seed pod. If we dissect it and take careful notes, we can learn about de normal, smaller seed pods and easily see how de anatomy works.\n\nI need you to bring me more of dese mature anchor pods.  If my theory is correct, den we could actually have a factual record for de future.", progress = "I just finished with my notes from dissecting de massive seed pod. Do you have de other seed pods for comparison?", completion = "I am still unsure as to how dis thing got so big, but I am willing to believe dat it is a gift from de Loa.\n\nDat said, when I was dissecting de big pod, I noticed dat what I thought were just thick walls along de exterior of de pod were actually a separate chamber full of seeds! See? If you carefully trim and peel back de skin on de normal pod, you can harvest some extra seeds.", objectives = "Collect 9 Mature Anchor Pods from anchor weed.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[51482] = { id = 51482, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seeking More Knowledge", description = "One of de most sacred plants on dis island is anchor weed. Legend says dat it was a gift from de Loa and it can do anything from regrow limbs to granting immortality.\n\nIf you are looking for facts as to what it can do or how to harvest it, you will need to go elsewhere. \n\nThe spirits tell me dat dere is a book, dat contains de information you seek. Look for it deep within the Waycrest Manor.\n\nDey ask dat in exchange for dis knowledge, you kill whatever is causing a rift in de spirit world.", progress = "Have you retrieved de book?", completion = "Dis thing is in terrible condition. Did it have dis much blood on it when you found it?\n\n<Several moments pass as Jahden flips through the pages>\n\nHmm... It is hard to tell from dese pictures, but it looks like de seed pods open when the plant is disturbed.\n\nHowever, if de first cut is at de base, dat drains a reservoir of water dat is used to open and close de pods.  So, start at the bottom, working your way up, and you should get a better harvest.", objectives = "Retrieve the Treatise on Anchor Weed from within Waycrest Manor.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[51483] = { id = 51483, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heritage o' the Dark Iron", description = "Ye've done us proud, {name}. I've heard tales o' yer bravery during yer journeys across the surface o' Azeroth.\n\nReturn tae the mountain. We've got somethin' special fer ye.", completion = "The Dark Irons never had it easy in this world. But with champions like ye tae fight for 'em, our allies know the courage that burns in our hearts.\n\nEnough fancy banter! Take this armor, then let's toast yer courage with a mug o' cold brew!", objectives = "Meet Moira Thaurissan at Shadowforge City.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[51484] = { id = 51484, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heritage of the Mag'har", description = "You have fought countless battles across the face of Azeroth. You have shown both our allies and enemies what it means to be Mag'har!\n\nReturn to Orgrimmar that I may recognize your dedication to our people.", completion = "Though Draenor is lost to us, we will never forget our ancestral home... or those who were lost in the fight for our freedom.\n\nYour victories in Azeroth prove that our people have earned a place in the Horde. It pleases me to honor you with this symbol of our proud lineage.", objectives = "Meet Overlord Geya'rah in Orgrimmar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[51485] = { id = 51485, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "For the Horde", description = "The Mag'har face a new future, {class}.\n\nDraenor has fallen. We cannot know if we will ever set eyes upon our homeland again. But this is not the time to wallow in past sorrows.\n\nDestiny is ours to decide. Orgrimmar is our home now, and we must make our mark upon this land!\n\nShow our allies in the Horde what it means to be Mag'har. Meet with the ambassador at the warchief's embassy, then go forth and claim victories across Azeroth.\n\nStrength and honor, {name}!", completion = "Are you the new one? I'm supposed to welcome you. Here, take this letter.\n\n<Blackguard lets out an exasperated sigh.>", objectives = "Meet Ambassador Blackguard at the Orgrimmar Embassy.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[51486] = { id = 51486, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fer the Alliance", completion = "Ah, there you are, {name}! We've been inspecting--err--expecting you!", objectives = "Meet Ambassador Moorgard at the Stormwind Embassy.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[51487] = { id = 51487, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Searching for Answers", description = "There's a saying Cyrus always said when I was a kid: \"The best face is a friendly one.\" It's really helped me get to know the visitors from all over the world that come through Boralus.\n\nLet's ask some of the people in charge around here and see if they know anything about the fleet. Maybe it's just a matter of asking nicely!", progress = "I figure, worst case is we make a few friends!", completion = "No luck just yet, but I think we're making progress.", objectives = "Question Sister Adrianna, Brother Darrel, and Sister Cecilia for information about the missing fleet.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[51488] = { id = 51488, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Archived Knowledge", description = "It seems like this Brother Alen we keep hearing about might have some answers. \n\nAt least, I sure hope so. Everyone here seems a bit... evasive.\n\nI think I saw some archivists heading into the southern cloister. If we follow them, I bet we'll find Alen too.", progress = "This place is way bigger than it looks!", completion = "I'd rather not stick around to see if he's right.", objectives = "Question Brother Alen for information about the missing fleet.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[51489] = { id = 51489, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Time to Leave", description = "I knew it! I knew the fleet wasn't just lost!\n\nWe may be a little in over our heads here. Let's leave before things get out of hand.\n\nGaleheart can take us to Stormsong Valley from here. No point in following tradition at this point, right?", completion = "What's going on here?!", objectives = "Travel on Galeheart to Stormsong Valley.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[51490] = { id = 51490, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Border Issues", description = "They've closed off the entire valley! No wonder so many people have been complaining about trading with the Brennadam market.\n\nWe have to do something about this. These people need to make a living!\n\nYou're going to have to be an honorary cadet for me here, {name}. Tell these ruffians to clear the road!", progress = "We have to stop this!", completion = "Good work! Now these fine people can go about their lives.", objectives = "Convince the House Stormsong militia to clear the blockade.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[51491] = { id = 51491, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Balethorn" }
quests[51492] = { id = 51492, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gunpowder Plot", description = "Granny has everyone out running errands trying to put our hamlet back in order.\n\nI don't know what to do. The rats have gotten into our stores, they're eating everything in sight.\n\nI tried prodding one of them to get it to move along, it started foaming at the mouth, then it exploded! \n\nThink I know where all the gunpowder went...\n\nIf you recover any, can you please take it back to Marie?", progress = "Were you able to find any powder, dear?", completion = "Thank you so much. I wish Charles was half as studious as you.", objectives = "Collect 100 Gunpowder from Volatile Rats.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[51494] = { id = 51494, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Blood Gate" }
quests[51496] = { id = 51496, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Loa Your Standards" }
quests[51497] = { id = 51497, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hex Education" }
quests[51498] = { id = 51498, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cultural Significance", description = "I have noticed dat your skill with harvesting plants has improved, but I have also noticed dat you just treat each flower and leaf as a commodity. De flora of dese islands have a rich history, with a deep cultural significance to us.\n\nGo down to the Port of Zandalar, and ask some of the men and women what a sea stalk means to them.  Learn from us, and l will make it worth your while.", completion = "De sea stalk has a unique magical property dat allows de stalk to provide de flower water, even if de flower is cut off.\n\nSailors will give their loved ones a flower and keep de stalk on themselves, so if dey fall over board, de salt water kills de flower. What you hold is more dan a stick, it is a family member's life.\n\nAs for your lesson, unlike most other magic plants, de best material to harvest for magical essence is de stem, not de leaves or flower.", objectives = "Learn the importance of sea stalks from people in the Port of Zandalar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[51500] = { id = 51500, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kings' Rest: The Weaponmaster Walks Again" }
quests[51501] = { id = 51501, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kings' Rest: Malfunction Junction" }
quests[51502] = { id = 51502, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kings' Rest: Kingsguard" }
quests[51503] = { id = 51503, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gathering Mementos", description = "I have a task dat I can not really trust to anyone else, and I feel you could handle it with de reverence it deserves.\n\nAn old friend came to me today, bringing a wilted sea stalk flower with her. Her husband was on a ship off the coast of Nazmir. I am unsure if de ship went down because of de naga, de Alliance, or a squall, but she said she did not want revenge.  Only closure.\n\nIf you could go get her something to remember him by, I will tell you everything I know about sea stalks.", progress = "Have you had a chance to search de wreckage?", completion = "I can not thank you enough for dis.\n\nDeath seems to always haunt dis land, but it is somewhat lessened by de thought dat we can still hold on to de memories of those departed.\n\nAs for your lesson, de last bit of advice I can give you is simple. To help you get de most of each sea stalk, instead of cutting the stem off from de plant, carefully pull it out of de sand and tear off de roots.", objectives = "Search through patches of sea weed to find a memento of the lost sailor.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[51504] = { id = 51504, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cookie Delivery", description = "Before you head out, dear, I have one more favor to ask of you.\n\nPlease take these cookies with you to Charles.\n\nWhat sort of grandmother would I be if I didn't bake some for him too!?\n\nA terrible one, that's what, and I've no wish to be accused of that!", progress = "Are those cookies I smell!?", completion = "Cookies, for me!? Thank you!", objectives = "Deliver Box of Cookies to Charles Davenport in the Sprucewood.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[51505] = { id = 51505, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Quillrat Matriarch" }
quests[51506] = { id = 51506, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Barbthorn Queen" }
quests[51507] = { id = 51507, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gorehorn" }
quests[51508] = { id = 51508, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vicemaul" }
quests[51512] = { id = 51512, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bilefang Mother" }
quests[51513] = { id = 51513, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zalazane Returns", description = "{name}, I have never needed your help as much as I do this day. My home be under attack.\n\nI only just heard myself. Master Gadrin be callin' for aid. Zalazane, an old enemy of da Darkspear, has returned to da Echo Isles and has brought with him an army of da dead.\n\nZalazane be a traitor who has slain many Darkspear and defiled their souls. Will you come with me to defeat him? We can take da ship dat departs da Port of Zandalar.", completion = "You... you brought da Zandalari with you?", objectives = "Reach Master Gadrin in the Echo Isles.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[51514] = { id = 51514, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Broken Bargain", description = "These mindless undead just keep coming. They be far stronger than they were the last time Zalazane walked this world.\n\nPlease, help us drive these undead back.", completion = "The dead should stay dead.", objectives = "Destroy 20 Mindless Trolls on Darkspear Isle.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[51515] = { id = 51515, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vengeance for Vol'jin", description = "If we mean to destroy Zalazane then we gonna need something that can damage that spirit.\n\nDa Glaive of Vol'jin might be what we need to do this.\n\nZalazane be hovering near where he fell so many years ago. Rokhan and Talanji have already gone to face him.\n\nGo, slay Zalazane, and then plunge da glaive into the spirit before it can escape. Let us hope de bargain Vol'jin made be powerful enough to destroy this enemy.", progress = "Zalazane has plagued the Darkspear longer than any enemy we ever faced. His destruction must happen swiftly.", completion = "Da blade... it be glowin'. It never did dat before.", objectives = "Destroy Zalazane.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[51516] = { id = 51516, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Atal'Dazar: Ashes of a Warchief", description = "I have learned much of de Darkspear lately. Truth is, I have quietly admired dem since I was a little girl, hearin' of Vol'jin's defiance of Zul's reckless call to action.\n\nVol'jin was Warchief of the Horde, chieftain of de Darkspear, and more troll den most can claim to be.\n\nHis ashes should be honored in a place of kings and queens.\n\nTake de ashes to Atal'Dazar with my blessing and honor your former Warchief as he deserves.", progress = "What you doin' my friend?", completion = "You and I need be talkin'.", objectives = "Bring Vol'jin's ashes to Atal'Dazar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[51517] = { id = 51517, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "You Owe Me a Spirit", description = "Ya not leaving that here.\n\nOl' Vol'jin not be dancin' in my house. I not be seein' his spirit for a long time.\n\nIts absence has broken de bonds dat held Zalazane in my control.\n\nSo... I want you to lift dat heavy urn, and bring it to my necropolis.\n\nVol'jin and I gonna have a face to face on my ground.", completion = "I have waited some time for dis. Long overdue hee hee... wait a moment.", objectives = "Bring the Urn of Vol'jin to Bwonsamdi in Nazmir.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[51518] = { id = 51518, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Lost Spirit", description = "It high time you an' I had a talk about ol' Vol'jin's missin' spirit. \n\nDis goes beyond simple bargains and rights of passage. Spirits don' just go missin'.\n\nYou gotta few friends dat are gonna help ya track Vol'jin's spirit down. Dem who was friends to him in life should have da strength to find him in death. And if not, Talanji gonna help ya.  \n\nGo to Talanji's ship in da Port of Zandalar. It be dat banged up ship ya came in on. You gonna do a little seance.", completion = "I am here because Master Gadrin and Rokhan asked for my aid and it is my gratitude for their deeds and yours that makes me willing to do this.\n\nNOT because Bwonsamdi insisted.\n\nIf he can't keep track of his own spirits that is a \"him\" problem, not a \"me\" problem.", objectives = "Speak with Princess Talanji in the Port of Zandalar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[51519] = { id = 51519, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spirit Call", description = "We gonna be reachin' far into de Shadowlands for this. If Vol'jin has gone beyond Bwonsamdi's vision than either he be lost somewhere or hiding.\n\nEither way, I am hoping the bond he shares with de gathered Darkspear here can help bring him to us.\n\nStay close and don't interrupt de ritual once it has begun.", completion = "'Ello mon.", objectives = "Observe Talanji's ritual.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[51520] = { id = 51520, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Justice for the Fallen", description = "Justice for da sons and daughters of lost loa. Justice for da heart of Zandalar. G'huun must be slain, and a symbol of his death displayed to those who need see it most.\n\nTake me glaive, drive it into da corpse of dat beast, and let Talanji show it to her people.\n\nLet peace be started in da hearts of da Zandalari.", progress = "Madness and darkness be movin' on da other side. Da pain of so many be mighty.", completion = "Dis been a foe that threatened da trolls for many generations. We may not have always known his name, but we felt his curse.\n\nToday, you won da justice for thousands of generations of trolls.", objectives = "Bloody the Glaive of Vol'jin in G'huun's corpse.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[51521] = { id = 51521, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The True Leader of Zandalar", description = "Now, take me glaive and walk with Talanji. Let her present your victory to her people. Let da trolls know justice, and the strength of a leader.", completion = "Talanji is da true ruler of Zandalar, even if she be doubting it. With guidance, she will eclipse her father's reign.\n\nFor now, ya have me thanks.", objectives = "Present the Glaive of Vol'jin with Talanji to the people of Zandalar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[51526] = { id = 51526, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Warlord's Call", description = "Warfang Hold is our best position on Kul Tiras. We can not allow it to fall!\n\nThe Warchief has placed High Warlord Cromush in charge of our reinforcement efforts, you are ordered to report to him as soon as possible.", completion = "Hurry up and get yourself squared away, {name}. We've got a battle to get to.", objectives = "Report to High Warlord Cromush in Zuldazar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[51527] = { id = 51527, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Executioner Blackwell" }
quests[51528] = { id = 51528, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Captain Leadfist" }
quests[51529] = { id = 51529, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Talon" }
quests[51530] = { id = 51530, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wedding Crashers" }
quests[51532] = { id = 51532, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Storming In", description = "Front and center, {name}!\n\nAs of last night, we received word that Rexxar's force at Warfang Hold in Stormsong was surrounded by a Kul Tiran army and an attack is imminent.\n\nAs soon as you have your things packed, go speak with Dread-Admiral Tattersail and we'll get underway. There's no time to waste!", completion = "I don't know what foul sorcery those Kul Tirans used upon our ships, but right now our men are being pushed to the shore with nowhere to evacuate!\n\nNo time to puzzle things over, we have to act now!", objectives = "Speak with Dread-Admiral Tattersail.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[51533] = { id = 51533, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Glaive of Vol'jin", description = "When fighting someone who has escaped the grasp of Bwonsamdi, as Zalazane has, it is best to bring weapons that can hurt him.\n\nIn Darkspear Hold you will find the Glaive of Vol'jin.\n\nIt should have enough bond with Vol'jin's spirit to aid us in this fight.", progress = "Did you find the glaive?", completion = "The bond between Vol'jin and Zalazane was one of magic and bargains with loa.\n\nThe bond between Vol'jin and dis weapon was also great. Dis may be what we need to finally destroy that spirit.", objectives = "Obtain the Glaive of Vol'jin.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[51534] = { id = 51534, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Battle for Brennadam", objectives = "Collect 1 Salvaged Bullets.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[51535] = { id = 51535, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Veteran's Summons", description = "{name}, we received word from Orgrimmar. Eitrigg has requested a meeting. Says it's important. He left a letter for you.\n\nI wouldn't keep him waiting or he might expire of old age before you find out what he wants.", sourceObjective = "Meet Eitrigg at the Orgrimmar Embassy.", sourceObjectiveStatus = "unverified-source-field" }
quests[51536] = { id = 51536, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "On the Hunt", description = "Looks like the magic the Kul Tirans used on our ships is beginning to dissipate, but I'm sure what happened to our ships here is only just the beginning.\n\nGet to the shore. We need to contact the survivors and find out just what we're up against.", completion = "Thank you, friend.\n\nThese humans have made a grave error today.", objectives = "Search Seawatch Point for survivors.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[51538] = { id = 51538, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Word from the Deep", description = "A dark soul has infiltrated the Zanchuli Council, seeking an accord with Queen Azshara.\n\nSome followed, through greed or fear. Others were too trusting and believed his lies.\n\nWe fall, one by one. They will soon clear the path of resistance.\n\nAzshara's motives are hidden behind a vast darkness. She reaches into a place from where she cannot return.\n\nI would pity her, but she killed my followers...\n\nWhen the time comes, I will rip her apart.", completion = "It seems the naga have moved up in threat level from \"mere nuisance\". These are dark days indeed.", objectives = "Share Gral's warning with the Seekers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[51539] = { id = 51539, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Inform the Horde!", description = "This was all perpetrated by someone on the Zanchuli Council. \n\nThey sacrificed their own people, Gral's followers, for Azshara. That is unconscionable!\n\nThey weaken the foundation, so the kingdom will fall.\n\nOne of your people must have direct access to the king. Anyone else could be the traitor.", completion = "It was wise of you to bring this to me, {name}.", objectives = "Warn Baine of the betrayal.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[51540] = { id = 51540, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Explosive Situation", description = "<This crate has fallen into the water. It contains bombs built to take out large mechanical devices.>\n\n<If we had more of them, we could destroy the Venture Company's Reef Breaker.>", progress = "You'll need more of these bombs if we want to destroy the Reef Breaker.", completion = "Many battles are won by those who take the initiative and exploit an opportunity. You have spotted an excellent opportunity.  \n\nNow you should exploit it!", objectives = "Collect 5 Bot Buster Bombs.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[51541] = { id = 51541, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arclight" }
quests[51542] = { id = 51542, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Avalanche" }
quests[51543] = { id = 51543, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Saplings in the Snow", description = "Be wary mainlander, dangers lurk nearby. \n\nOne such creature, Greenstalker, used to be an ally. In his corrupted, mindless rage he nearly killed my brother and I while we were trying to help someone in the wilds. There is something which might help but I must tend to my brother's wounds and cannot obtain the remaining item on my own.\n\nPlease go onto the mountainside and pull some saplings out of the earth for me. The plants here are healthy and their roots run deep so they won't come easily.", progress = "Did you find the mountain saplings I need?", completion = "Thank you for returning quickly. These are new growth, full of potent life-giving energy and a necessary sacrifice to cleanse corruption.\n\nGive me a moment as I create the charm.", objectives = "Collect 6 Mountain Saplings.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[51544] = { id = 51544, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Disarming the Cannons", description = "With your arrival, our salvation may have arrived. Your rowboats will serve as a way for us to evacuate the most critically injured.\n\nUnfortunately, the Horde have brought in a ship, and there's no way we can get our boats past their blockade.\n\nWhile the rest of us load our injured on the boats, we need you to infiltrate their ship and disable those cannons.", completion = "Now we can get our wounded to safety.", objectives = "Disable the cannons on the Horde ship.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[51545] = { id = 51545, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Breaker Bad", description = "The combined fire power of all the bombs you have collected should be able to destroy the Venture Companies Reef Breaker.\n\nIt's time to act and protect the reef and this sacred cave.", completion = "You have done us a great service.", objectives = "Destroy the Reef Breaker.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[51546] = { id = 51546, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "It's the Pits" }
quests[51547] = { id = 51547, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "WANTED: Rindlewoe", description = "A monstrous beast of wood and flesh has been terrorizing the nearby river territories.\n\nIf any adventurers are brave enough to vanquish this beast, the town of Fallhaven would gratefully proffer a reward.\n\nPlease report to Mayor White if you wish to help.", progress = "Yes?", completion = "The beast has been slain? You have my thanks, {class}.\n\nHere is your reward, as promised.", objectives = "Defeat Rindlewoe outside of Fallhaven.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[51548] = { id = 51548, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nagative Feedback" }
quests[51550] = { id = 51550, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bubbles and Trouble" }
quests[51552] = { id = 51552, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Days Are Just Packed", description = "Hello there! Would you mind checking on someone for me?\n\nSergeant Calvin was supposed to meet me here. We were going to go out looking for new alchemical reagents, but he hasn't shown up yet.\n\nI know the militia has been really busy lately so I guess he's busy, but he should still be in Brennadam Square. Would you mind checking in on him?", completion = "This can't be happening...", objectives = "Find Sergeant Calvin in Brennadam Square.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[51554] = { id = 51554, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reloading", description = "Daryl's making every shot count, but there's just too many Horde. We're going to need more ammo soon!\n\nI need you to take this note to my uncle Leo at Deadwash, he'll be able to help.", completion = "Lea Martin?  She's a tough one!  I'll try to help her, but we gotta save our people first.", objectives = "Deliver the note to Leo Shealds.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[51555] = { id = 51555, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Keep Them On Task", description = "Princess Talanji's actions have thrown off our pursuers. Her loa is powerful indeed.\n\nWe need to be certain if there were survivors, they do not gain a foothold on Zandalar. I am concerned that our Forsaken compatriots might get... overzealous. Please keep an eye on them, and remind them of what is honorable.", completion = "You've been sent to check up on me?", objectives = "Speak with Dennis Grimtale at Talanji's Rebuke.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[51556] = { id = 51556, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Myself Again", description = "I joined the tidesages because I wanted to show my brother I wasn't a weakling.  \n\nI loved the magic and power, but I started to do unspeakable things. I even tried to hurt my own family.\n\nPlease get word to my brother at Dire Hills Lodge. Tell him I have come to my senses. I am myself again.", completion = "It's just like Julian to realize his mistakes long after he's done harm to others.  I hope he finds his way, but right now I have people here to worry about.", objectives = "Speak to Patrick Eckhart at Dire Hills Lodge.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[51557] = { id = 51557, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Irontide Warning", description = "Horde's taking this town! I'm not gonna stick around to watch!\n\nYou could help me out though. Go see Leo Shealds in Deadwash.  \n\nTell him, Irontide is still coming and we're taking the gold!", sourceObjective = "Speak to Leo Shealds at Deadwash.Horde's taking this town! I'm not gonna stick around to watch!\n\nYou could help me out though. Go see Leo Shealds in Deadwash. \n\nTell him, Irontide is still coming and we're taking the gold!", sourceObjectiveStatus = "unverified-source-field" }
