quests[51566] = { id = 51566, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Resurgence of the Beast" }
quests[51568] = { id = 51568, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ritualistic Preparations", description = "Hey! I just got a request for a shipment of storm silver. Wanna help? \n\nAs you know, storm silver is lightweight and resists corrosion. What you may not know is that we use it throughout our ships. It's so light our marines and pirates use it for armor because they can swim in it!\n\nHowever, any parts that go onto a ship have to be blessed by a tidesage, or it'll be cursed to a watery doom!\n\nHarvest a bucketful of ore, smelt it, and get it blessed for me, and I will teach you how to mine it easier.", progress = "Did you get the storm silver? Don't forget that it needs to be blessed.", completion = "Good work! These look great!\n\nThese bars will be used as part of our next warship.\n\nNow then, you scratched my back, and I will scratch yours. Storm silver is very brittle naturally. When you mine it, use several small swings instead of one big one. That'll keep the metal from being chipped away.", objectives = "Mine Unsanctified Storm Silver Ore, use a forge to smelt Unsanctified Storm Silver Ingots, then get them blessed by a tidesage.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[51569] = { id = 51569, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Zandalar Campaign", description = "It is time that we begin to think of our enemy, {name}. The Horde spreads its influence throughout Zandalar unchecked.\n\nKing Anduin has charged us with establishing footholds in the areas of Zuldazar, Nazmir, and Vol'dun.\n\nI have taken the liberty of deploying some of our forces in key locations, but each will need a firm hand--your hand--to direct our efforts.\n\nWhich location shall we secure first?", completion = "A fine choice, {name}.", objectives = "Use the Zandalar Campaign Map to choose a foothold.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[51570] = { id = 51570, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Foothold: Zuldazar", description = "Zuldazar is the seat o' power fer the Zandalar empire.\n\nI've deployed some o' me mole machines in a place called Xibala. There's a nearby Azerite deposit that'll be o' great interest to the King. My lads say they're under attack.\n\n                 - Moira Thaurissan", completion = "You have chosen to sail to Zuldazar.", objectives = "Assist Kelsey Steelspark in Zuldazar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[51571] = { id = 51571, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Foothold: Nazmir", description = "The swamp of Nazmir is home to the notorious blood trolls.\n\nCaptain Conrad has been dispatched to determine how we can use their hatred toward the Zandalari to our advantage. Reports from the jungle have proven disconcerting at best.\n\n                     - Mathias Shaw", completion = "You have chosen to sail to Nazmir.", objectives = "Assist Brann Bronzebeard in Nazmir.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[51572] = { id = 51572, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Foothold: Vol'dun", description = "The desert of Vol'dun has a promising harbor for our fleet.\n\nAn indigenous snake people known as the sethrak occupy the area. They are aggressive and cannot be negotiated with. We have little choice but to eliminate them.\n\n                    - Magister Umbric", sourceObjective = "Assist Alliance forces in Vol'dun.", sourceObjectiveStatus = "unverified-source-field" }
quests[51573] = { id = 51573, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "I've Got Your Back", description = "It's good to see a new face around here. I've got a problem and you look like you can handle a fight.\n\nDat group of murderous thugs over dere are looking for trouble and I need someone to back me up.\n\nDe truth is dat I used to be one of dem myself, but I left for a second chance at an honest life.\n\nI need to convince Mojambo and his henchmons to leave before dey start causing trouble for de rest of de outcasts here.", progress = "Mojambo isn't going to back down easily.", completion = "Mojambo will come back with all his minions. And when he does... dere will be blood.", objectives = "Guard Razgaji while he meets with Mojambo.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[51574] = { id = 51574, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Freshly Squeezed", description = "Is this troll a friend of yours? I'm so glad Kiro let me keep her. \n\nHe's a bit wary of outsiders, but he's a great healer. \n\nShe'll wake up, I promise. And when she does, she'll be thirsty.\n\nThe sands are short on water, but you're in luck. The grove that surrounds this camp is filled with pricklevines. \n\nYou wouldn't want to eat the flesh, but the liquid inside can quench any thirst.\n\nJust give them a good squeeze to collect their juice.", progress = "Do you have the juice? Your friend will be thirsty when she wakes.", completion = "That's a lot of juice!", objectives = "Collect 8 Pricklevine Juice.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[51575] = { id = 51575, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lost But Not Forgotten", description = "Hey, {name}, would you be interested in getting back a personal possession?\n\nDere is a raptor in Xibala dat took an ancient and valuable artifact from my people. My attempts to negotiate with de beast have not gone well, resulting mostly in mutual screaming and biting.\n\nFind de raptor Bonescreamer, kill it, and bring me de lost artifact.\n\nIn return, I will show you how to skin dese beasts of de land more effectively.", progress = "Have you slain de beast yet?\n\n<Rana chuckles as she smiles slyly.>", completion = "Ah ha! Would you look at dat! I thought I would never see you again!\n\n<Rana snuggles the small stuffed raptor happily.>\n\nWhat is with dat face? I told the truth.\n\nI lost it when I was a child, so that is practically a lifetime ago, it has tremendous sentimental value to me, and I am one of my people.\n\nBut, you did do as I had asked, so I will teach you a little something.\n\n<Rana joyfully explains some of the more elusive techniques to harvesting leather.>", objectives = "Kill Bonescreamer and bring the 'Ancient Artifact' to Rana the Cutta.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[51576] = { id = 51576, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Any Witch Way but Dead" }
